customCSS:
.t, .history { color: #555555; }
.join { color: #ade46b; }
.part, .quit { color: #555555; }
.kick, .error { color: #ea5965; }
.notice { color: #fec254; }
.action { color: #c9aeff; }
.mode, .nick, .topic, .server { color: #86e2bf; }
.highlight { color: #d0cec3; background-color: #252d37; border-left: 3px solid #c9aeff; padding-left: 8px; }
.reply { color: #555555; border-left: 2px solid #2d91d0; padding-left: 6px; }
.oper { color: #191d26; background-color: #fec254; }
.reactions { color: #2d91d0; background-color: #252d37; }
.card { background-color: #252d37; border-color: #555555; }
.card-title { color: #2d91d0; }
.card-desc { color: #555555; }
.daychange { color: #555555; border-color: #252d37; }
